package com.ruoyi.system.domain.shop;
import com.ruoyi.common.annotation.Excel;
import com.ruoyi.common.core.domain.BaseEntity;
public class MallMember extends BaseEntity { @Excel(name="会员ID", cellType=Excel.ColumnType.NUMERIC) private Long memberId; private String appId; private String openId; private String unionId; @Excel(name="昵称") private String nickname; private String avatarUrl; @Excel(name="手机号") private String phone; @Excel(name="状态", readConverterExp="0=正常,1=禁用") private String status; public Long getMemberId(){return memberId;} public void setMemberId(Long v){memberId=v;} public String getAppId(){return appId;} public void setAppId(String v){appId=v;} public String getOpenId(){return openId;} public void setOpenId(String v){openId=v;} public String getUnionId(){return unionId;} public void setUnionId(String v){unionId=v;} public String getNickname(){return nickname;} public void setNickname(String v){nickname=v;} public String getAvatarUrl(){return avatarUrl;} public void setAvatarUrl(String v){avatarUrl=v;} public String getPhone(){return phone;} public void setPhone(String v){phone=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} }
